import {renderDevelopmentSpec} from './development-spec.js?v=10';
import {levelCredential,chamberLogo} from './credentials.js';
import {renderMarketplace} from './marketplace.js?v=7';
import {dimensions,levels,institutions,courses,categories,provinces,getInstitution,assessment,findCourses} from './model.js';
const main=document.querySelector('#main');
document.querySelector('.skip').onclick=e=>{e.preventDefault();main.focus();main.scrollIntoView()};
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS',maximumFractionDigits:0}).format(n);
const number=n=>new Intl.NumberFormat('es-AR').format(n);
const icons={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',book:'<path d="M12 5v16M3 4c4-1 6 0 9 2 3-2 5-3 9-2v14c-4-1-6 0-9 2-3-2-5-3-9-2Z"/>',screen:'<rect x="3" y="4" width="18" height="13" rx="2"/><path d="M8 21h8m-4-4v4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',level:'<path d="M4 20v-5h4v5m2 0V9h4v11m2 0V3h4v17"/>',check:'<path d="m5 12 4 4L19 6"/>',filter:'<path d="M3 6h18M6 12h12M9 18h6"/>',tool:'<path d="m14 6 4 4M4 20l7-7m1-10a7 7 0 0 0 9 9l-4-4 1-4-4 1Z"/>',message:'<path d="M21 11a9 9 0 0 1-9 9 9 9 0 0 1-4-1l-5 2 1-5a9 9 0 1 1 17-5Z"/>'};
const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.book}</svg>`;
const badge=i=>{const a=assessment(i);return `<a class="badge ${a.tone}" href="#/instituto/${i.id}" title="Ver evaluación de ${escape(i.name)}">${icon('level',12)}${a.name}</a>`};
const catStyle=c=>({'Tecnología':['technology','screen'],'Comunicación':['communication','message'],'Oficios':['trade','tool'],'Idiomas':['language','message'],'Gastronomía':['food','book']}[c]||['','book']);
const rating=c=>c.rating?`<span class="stars" aria-label="Estrella">★</span><strong>${c.rating.toLocaleString('es-AR',{minimumFractionDigits:1})}</strong> <span>(${c.reviews} opiniones de ejemplo)</span>`:'Todavía sin opiniones';
const crumbs=(label,parent='Buscar cursos',path='buscar')=>`<div class="breadcrumb"><a href="#/${path}">${parent}</a><span>/</span><span>${escape(label)}</span></div>`;
function levelsPage(){main.innerHTML=`<div class="page"><div class="page-heading"><span class="eyebrow">INFORMACIÓN PARA ELEGIR</span><h1>Sello de Desarrollo Formativo.</h1><p>Una credencial de la Cámara que muestra el nivel de cada instituto y la evidencia que lo sostiene. Su escala es independiente de la dificultad de los cursos.</p></div><div class="notice"><strong>Metodología de demostración, pendiente de validación por la Cámara.</strong> Los niveles no son acreditaciones oficiales. En este prototipo no se evalúa a ningún socio real. La evolución del modelo para contemplar socios nuevos está documentada en la <a class="text-link" href="#/propuesta/desarrollo">guía de evaluación progresiva para desarrollo</a>; todavía no se aplica al catálogo de ejemplo.</div><div class="credential-levels">${levels.map(l=>`<div>${levelCredential(l)}<p class="level-range">Umbral propuesto: ${l.min}–${l.max} puntos${l.key==='referente'?' + requisitos de evidencia':''}.</p></div>`).join('')}</div><div class="notice"><strong>En evaluación:</strong> estado separado de la escala para instituciones con evidencia insuficiente. Sin datos no significa mal evaluado. La identidad verificada se muestra como una condición independiente.</div><section class="section two-col"><div><span class="eyebrow">CINCO DIMENSIONES · 100 PUNTOS</span><h2>Cómo se compone el nivel</h2>${dimensions.map(d=>`<div class="weight-row"><div><h3>${d.name}</h3><p>${d.description}</p></div><strong>${d.weight}%</strong></div>`).join('')}</div><div class="content-panel"><h2>Reglas que lo hacen justo</h2><ul><li>Publicar un puntaje sólo con las cinco dimensiones evaluadas, al menos 10 opiniones verificadas de los últimos 24 meses y revisión de la Cámara.</li><li>Para ser Referente: al menos 85 puntos, 30 opiniones verificadas y 80/100 en propuesta formativa. Si no se cumplen, el máximo es Distinción formativa.</li><li>Limitar la incidencia del volumen a 10 puntos. Comparar actividad reciente dentro de áreas formativas y evitar que duplicar cursos mejore el nivel.</li><li>Ajustar las valoraciones por cantidad de opiniones. Un 5/5 con dos reseñas no debería superar automáticamente un 4,7/5 con cien.</li><li>Revisar trimestralmente, mostrar fecha y conservar historial. Una institución puede pedir una revisión con evidencia.</li><li>La pertenencia y los pagos a la Cámara no compran puntos. Los espacios patrocinados, si se incorporan, deben identificarse por separado.</li></ul></div></section><section class="section"><h2>Preguntas que vale la pena resolver</h2><details open><summary>¿Más certificados significa mejor formación?</summary><p>No. El número de certificados emitidos refleja volumen de actividad. No equivale a cantidad de alumnos únicos, tasa de finalización, satisfacción ni acreditaciones externas. En este modelo sólo aporta a la trayectoria, con un máximo de 10% del total.</p></details><details><summary>¿Cómo se ordenan los resultados de búsqueda?</summary><p>Primero se respetan la búsqueda y los filtros del usuario. Las coincidencias del título tienen más peso, seguidas por las habilidades, los resultados de aprendizaje y el programa. A igual coincidencia, se ordena alfabéticamente. El puntaje institucional no modifica la relevancia, ni siquiera en los empates. Podés elegir explícitamente ordenar por precio, opiniones o nivel institucional.</p></details><details><summary>¿Cómo se verifica una opinión?</summary><p>La propuesta es asociarla a una cursada comprobable, permitir una opinión por inscripción y moderar con reglas públicas. La institución puede responder, pero no eliminar una reseña por ser negativa. Deben mostrarse la cantidad de opiniones y su período, sin exponer datos personales de estudiantes.</p></details><details><summary>¿Cuáles son los datos nuevos que pediríamos a los socios?</summary><p>Por curso: programa actualizado, modalidad, horarios, próximas fechas, duración, precio total, requisitos, condiciones del certificado emitido por la Cámara, evaluación y canal de consulta; logo institucional, redes, video de presentación, clase de muestra y fotografías autorizadas. Como evidencia de calidad: docentes y antecedentes pertinentes, prácticas, rúbricas, acompañamiento y resultados de finalización con denominadores. Completar un campo ayuda a informar; afirmar algo sin evidencia no otorga una distinción.</p></details><details><summary>¿Cuándo se aplicaría a socios reales?</summary><p>Después de auditar los vínculos entre socios, cursos y certificados; acordar la rúbrica; probar sesgos por tamaño, antigüedad y especialidad; y habilitar revisión institucional. La primera versión real puede mostrar identidad verificada y actividad documentada mientras se reúne evidencia para los niveles.</p></details></section><section class="section content-panel"><h2>Construir confianza lleva evidencia.</h2><p style="margin-top:14px">El objetivo es orientar a quien busca y dar a cada socio un camino concreto de mejora. No declarar que un instituto es “bueno” o “malo” por tener más o menos registros.</p><p style="margin-top:18px"><a class="text-link" href="#/propuesta">Ver el alcance y la base de datos disponible</a></p></section></div>`}
function proposalPage(){main.innerHTML=`<div class="page">${crumbs('Propuesta del proyecto')}<div class="page-heading"><span class="eyebrow">PROPUESTA PARA LA CÁMARA</span><h1>Del catálogo a una decisión informada.</h1><p>Un buscador de educación no formal que conecta a las personas con cursos de socios y explica el respaldo de cada institución. “Forma” es un nombre de trabajo.</p></div><div class="notice">Este sitio es un prototipo funcional con datos ficticios. No consulta las bases productivas, no publica datos de estudiantes y no asigna niveles a socios reales.</div><section class="content-panel development-link"><span class="eyebrow">GUÍA PARA EL EQUIPO DE DESARROLLO</span><h2>Evaluación institucional y autogestión del socio</h2><p>Arquitectura del backend y conexión con la base de la Cámara, ranking, perfil público, gestión de leads y publicación de cursos.</p><a class="button" href="#/propuesta/desarrollo">Ver especificación para desarrollo</a></section><section class="section"><h2>La base de partida</h2><div class="stat-row" style="grid-template-columns:repeat(2,minmax(0,1fr))"><div class="stat"><strong>18.466</strong><span>Cursos en el informe local del 1/9/2026</span></div><div class="stat"><strong>137.601</strong><span>Registros de certificados con estado = 1, al 1/9/2026</span></div></div><p class="small">Son cortes históricos, no conteos en vivo. Los cursos corresponden a la última versión activa y aprobada por CourseId no eliminado. Los certificados reúnen tres tablas y no equivalen a personas únicas ni a acreditaciones.</p></section><section class="section"><h2>Qué podemos usar y qué falta</h2><div class="table-wrap"><table><thead><tr><th>Información</th><th>Evidencia encontrada en el proyecto</th><th>Uso propuesto</th></tr></thead><tbody><tr><td>Socios</td><td>Identidad institucional, provincia, localidad, fecha de alta, web y campos para redes sociales y canales institucionales.</td><td>Perfil con logo autorizado, redes sociales verificadas, filtros geográficos y contacto institucional confirmado.</td></tr><tr><td>Cursos</td><td>Título, categoría, objetivos, horas, modalidad codificada, evaluación, destinatarios, versiones y estados.</td><td>Catálogo por curso vigente. Confirmar significado de estados y modalidad y verificar oferta efectiva.</td></tr><tr><td>Certificados</td><td>Registros históricos asociados a socio y curso, con estados y fechas.</td><td>Actividad por período, después de conciliar identificadores, depurar duplicados y validar semántica.</td></tr><tr><td>Opiniones de cursantes</td><td>No se confirmó una fuente de reseñas verificadas en los archivos revisados.</td><td>Crear un circuito de opiniones vinculadas a cursadas. No usar la nota del certificado como satisfacción.</td></tr><tr><td>Oferta comercial vigente</td><td>No confirmada en el relevamiento: precio, cupos, horarios y próxima fecha de inicio.</td><td>Permitir que los socios actualicen estos datos y confirmar su fecha de vigencia.</td></tr><tr><td>Resultados educativos</td><td>No se confirmó cobertura comparable de inscriptos, finalización o inserción laboral.</td><td>Incorporarlos después con denominadores, períodos y evidencia; no inferirlos del número de certificados.</td></tr></tbody></table></div><p class="source-note">Fuentes internas revisadas: reports/camara-course-alignment/summary.json; reports/camara-certificate-categories/summary.json; reports/esep/schema.json; scripts y documentación de auditoría. Revisión documental: 4/10/2026. No se realizó una auditoría en vivo.</p></section><section class="section two-col"><div class="content-panel"><h2>La experiencia pública</h2><ul><li>Buscar por tema, habilidad o nombre del curso.</li><li>Filtrar modalidad, área, provincia del instituto, duración y nivel.</li><li>Leer resultados de aprendizaje, trabajo práctico, evaluación, programa, requisitos, certificado de la Cámara, precio y disponibilidad. Explorar fotos, videos de presentación y clases de muestra.</li><li>Ver el nivel institucional con su fundamento y las opiniones del curso por separado.</li><li>Contactar al instituto por su canal institucional verificado.</li></ul><p>Referencia de interacción: <a class="text-link" href="https://www.emagister.com/" target="_blank" rel="noopener noreferrer">buscador de Emagister</a> y su <a class="text-link" href="https://www.emagister.com/centros.htm" target="_blank" rel="noopener noreferrer">directorio de centros</a>. La nueva presentación adopta patrones de marketplace: tarjetas visuales, logo del instituto, galería audiovisual y acceso claro a la consulta. La identidad visual y la metodología propuestas aquí son propias.</p></div><div class="content-panel"><h2>El incentivo para los socios</h2><ul><li>Recibir consultas de personas interesadas en su oferta.</li><li>Conocer qué evidencia falta y cómo mejorar su evaluación.</li><li>Actualizar los datos de sus cursos desde un portal institucional.</li><li>Consultar su evaluación e impugnar errores antes de su publicación.</li></ul><p>Como integración opcional futura, podrían vincularse habilidades con indicadores del Observatorio para ofrecer contexto sobre demanda laboral. Esto no convierte al Observatorio en el backend del portal ni en la fuente de los datos de socios, y no implica prometer empleo ni otorgar puntos por popularidad del área.</p></div></section><section class="section"><h2>Un lanzamiento en tres etapas</h2><div class="roadmap"><div class="content-panel"><span class="eyebrow">01 · CATÁLOGO VERIFICADO</span><h3>Buscar y encontrar</h3><p style="margin-top:12px">Conciliar identificadores, seleccionar la versión vigente, confirmar oferta y contactos. Publicar fichas de cursos y perfiles de socios con evidencia disponible.</p></div><div class="content-panel"><span class="eyebrow">02 · EVIDENCIA Y MEJORA</span><h3>Completar y verificar</h3><p style="margin-top:12px">Habilitar actualización por socios, recolección de opiniones verificadas y revisión de documentación. Calibrar la escala en un piloto interno.</p></div><div class="content-panel"><span class="eyebrow">03 · NIVELES PÚBLICOS</span><h3>Comparar con criterios</h3><p style="margin-top:12px">Publicar niveles con suficiente evidencia, metodología, fecha, revisión y apelación. Medir búsquedas sin resultados, consultas y actualización de fichas.</p></div></div></section><section class="section"><h2>Decisiones para validar antes de producción</h2><div class="content-panel"><ul><li>Nombre definitivo del buscador, alcance territorial y socios elegibles.</li><li>Certificación definida: el certificado lo emite la Cámara. Confirmar requisitos de aprobación, costos y procedimiento de emisión para cada curso.</li><li>Rúbrica por dimensión, pesos, umbrales, mínimos de opiniones y período de evaluación.</li><li>Responsables de verificar evidencia, resolver reclamos y revisar el nivel.</li><li>Reglas de publicación de cursos, campos obligatorios y plazo de actualización.</li></ul></div></section><section class="section"><h2>Conexión prevista con el sistema actual</h2><div class="content-panel"><p>El portal tendrá un backend propio, independiente del backend del Observatorio, con alojamiento e infraestructura todavía por definir. Ese backend deberá conectarse a la base de datos que utiliza el sistema de la Cámara: de allí saldrán los datos de los socios y los registros vinculados de cursos y certificados. Entregará al buscador sólo los campos públicos autorizados mediante una API; el navegador no accederá directamente a la base ni a sus credenciales.</p><p style="margin-top:16px">El catálogo necesita una correspondencia validada entre PartnerId, el identificador del socio, OldId y los cursos históricos. La ubicación de los datos nuevos —leads, opiniones, evidencias, revisiones y niveles— se definirá con el equipo del sistema de la Cámara, manteniendo sus vínculos con socios y cursos, la versión de la metodología y el historial de cálculo. La sincronización tendría que detectar cambios y despublicar oferta vencida o inactiva.</p></div></section></div>`}
function notFound(){main.innerHTML=`<div class="page"><div class="empty"><h1>No encontramos esta página</h1><p>Podés volver al catálogo y continuar tu búsqueda.</p><a class="button" href="#/buscar">Buscar cursos</a></div></div>`}
let previousRoute='';
function render(){if(location.hash.split('?')[0]==='#/comparar')history.replaceState(null,'','#/buscar');const parts=(location.hash||'#/buscar').split('?')[0].split('/'),route=parts[1],id=parts[2];document.querySelectorAll('[data-nav]').forEach(a=>{if(a.dataset.nav===route||(route==='instituto'&&a.dataset.nav==='instituciones'))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
 if(['buscar','curso','instituciones','instituto'].includes(route))renderMarketplace(route,id);else if(route==='niveles')levelsPage();else if(route==='propuesta'&&id==='desarrollo')renderDevelopmentSpec();else if(route==='propuesta')proposalPage();else notFound();
 document.title=`${route==='buscar'?'Buscá tu próxima formación':main.querySelector('h1')?.textContent||'Página no encontrada'} · Forma`;
 const nextRoute=parts.join('/');if(previousRoute&&previousRoute!==nextRoute){window.scrollTo(0,0);main.focus({preventScroll:true})}previousRoute=nextRoute;
}
window.addEventListener('hashchange',render);render();
// A progressive enhancement: unsupported browsers keep all visible controls.
const context=document.modelContext;
if(context?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
 try{Promise.resolve(context.registerTool({name:'search_demo_courses',title:'Buscar cursos de demostración',description:'Actualiza la búsqueda visible del catálogo ficticio de Forma. No consulta la base de socios real.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:200}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.query!=='string'||input.query.length>200||Object.keys(input).some(k=>k!=='query'))throw new Error('Se requiere query, un texto de hasta 200 caracteres.');const params=new URLSearchParams({q:input.query.trim()});history.replaceState(null,'',`#/buscar?${params}`);render();return {demo:true,results:findCourses({q:input.query.trim()}).map(c=>({id:c.id,title:c.title,institution:getInstitution(c.institution).name}))};}},{signal:lifecycle.signal})).catch(()=>{});}catch{/* Optional browser capability. */}
}
